import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js';
const client = new Client({ name: 'handbook-reader', version: '1' });
await client.connect(new StreamableHTTPClientTransport(
  new URL('http://127.0.0.1:3010/mcp')
));
try {
  const read = async (name, args) => {
    const result = await client.callTool({ name, arguments: args });
    if (result.isError) throw new Error(JSON.stringify(result.content));
    return result.structuredContent;
  };
  const tree = await read('list_documentation_tree', { system: 'shadcn' });
  const page = await read('get_documentation_page', {
    system: 'shadcn', section: 'technische-anbindung'
  });
  const button = await read('get_component_page', {
    system: 'shadcn', component: 'button'
  });
  console.log(tree.tree, page.updatedAt);
  console.log(button.contractReference, button.contract?.sources);
  console.log(button.contractArtifacts, button.implementations);
} finally {
  await client.close();
}
